## Picked stack: ship-fast mobile MVP

Use:

- **App:** Expo + React Native + TypeScript
- **Routing:** Expo Router
- **Backend/Auth/DB/Storage:** Supabase
- **Data fetching/cache:** TanStack Query
- **UI:** React Native Paper
- **Builds/releases:** EAS Build + EAS Update
- **Analytics later:** PostHog or Amplitude
- **Payments later:** RevenueCat

This is the fastest sane stack for iOS + Android without overbuilding.

---

## 1. Create the app

```bash
npx create-expo-app@latest mobile-app --template blank-typescript
cd mobile-app
```

Install core dependencies:

```bash
npx expo install expo-router react-native-screens react-native-safe-area-context expo-linking expo-constants expo-status-bar @react-native-async-storage/async-storage
npm install @supabase/supabase-js @tanstack/react-query react-native-paper react-native-url-polyfill zustand
```

Configure Expo Router:

```bash
npm pkg set main="expo-router/entry"
```

---

## 2. Add environment config

Create `.env.example`:

```env
EXPO_PUBLIC_SUPABASE_URL=
EXPO_PUBLIC_SUPABASE_ANON_KEY=
```

Create `.env`:

```env
EXPO_PUBLIC_SUPABASE_URL=https://your-project.supabase.co
EXPO_PUBLIC_SUPABASE_ANON_KEY=your-anon-key
```

---

## 3. Recommended folder structure

```txt
mobile-app/
  app/
    _layout.tsx
    index.tsx
    (auth)/
      sign-in.tsx
    (tabs)/
      _layout.tsx
      home.tsx
      settings.tsx
  lib/
    supabase.ts
    queryClient.ts
  providers/
    AuthProvider.tsx
  types/
    database.ts
  .env
```

---

## 4. Supabase client

Create `lib/supabase.ts`:

```ts
import 'react-native-url-polyfill/auto';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { createClient } from '@supabase/supabase-js';

const supabaseUrl = process.env.EXPO_PUBLIC_SUPABASE_URL!;
const supabaseAnonKey = process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY!;

export const supabase = createClient(supabaseUrl, supabaseAnonKey, {
  auth: {
    storage: AsyncStorage,
    autoRefreshToken: true,
    persistSession: true,
    detectSessionInUrl: false,
  },
});
```

---

## 5. Query client

Create `lib/queryClient.ts`:

```ts
import { QueryClient } from '@tanstack/react-query';

export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      retry: 1,
      staleTime: 30_000,
    },
  },
});
```

---

## 6. Auth provider

Create `providers/AuthProvider.tsx`:

```tsx
import { createContext, useContext, useEffect, useState } from 'react';
import type { Session } from '@supabase/supabase-js';
import { supabase } from '../lib/supabase';

type AuthContextValue = {
  session: Session | null;
  loading: boolean;
};

const AuthContext = createContext<AuthContextValue>({
  session: null,
  loading: true,
});

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => {
      setSession(data.session);
      setLoading(false);
    });

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((_event, nextSession) => {
      setSession(nextSession);
    });

    return () => {
      subscription.unsubscribe();
    };
  }, []);

  return (
    <AuthContext.Provider value={{ session, loading }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  return useContext(AuthContext);
}
```

---

## 7. Root layout

Create `app/_layout.tsx`:

```tsx
import { Slot } from 'expo-router';
import { QueryClientProvider } from '@tanstack/react-query';
import { PaperProvider } from 'react-native-paper';
import { StatusBar } from 'expo-status-bar';
import { queryClient } from '../lib/queryClient';
import { AuthProvider } from '../providers/AuthProvider';

export default function RootLayout() {
  return (
    <QueryClientProvider client={queryClient}>
      <PaperProvider>
        <AuthProvider>
          <Slot />
          <StatusBar style="auto" />
        </AuthProvider>
      </PaperProvider>
    </QueryClientProvider>
  );
}
```

---

## 8. Auth redirect

Create `app/index.tsx`:

```tsx
import { useEffect } from 'react';
import { ActivityIndicator, View } from 'react-native';
import { router } from 'expo-router';
import { useAuth } from '../providers/AuthProvider';

export default function Index() {
  const { session, loading } = useAuth();

  useEffect(() => {
    if (loading) return;

    if (session) {
      router.replace('/home');
    } else {
      router.replace('/sign-in');
    }
  }, [session, loading]);

  return (
    <View
      style={{
        flex: 1,
        alignItems: 'center',
        justifyContent: 'center',
      }}
    >
      <ActivityIndicator />
    </View>
  );
}
```

