}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    padding: 24,
    justifyContent: 'center',
  },
  title: {
    fontWeight: '700',
    marginBottom: 8,
  },
  button: {
    marginTop: 24,
  },
});
```

